// Pagination.tsx
import React from "react";

type PaginationProps = {
  currentPage: number;   // 1-based
  totalItems: number;
  pageSize: number;
  onPageChange: (page: number) => void;
  maxButtons?: number;   // max page buttons shown (default 7)
};

export function getPageCount(totalItems: number, pageSize: number): number {
  if (pageSize <= 0) return 1;
  // Always at least one page, so 0 results still renders "1".
  return Math.max(1, Math.ceil(totalItems / pageSize));
}

export function getPageRange(
  current: number,
  pageCount: number,
  maxButtons = 7
): number[] {
  // Exactly one page: the range is [1].
  if (pageCount <= 1) return [1];

  const size = Math.min(maxButtons, pageCount);
  let start = Math.max(1, current - Math.floor(size / 2));
  const end = Math.min(pageCount, start + size - 1);
  start = Math.max(1, end - size + 1);

  return Array.from({ length: end - start + 1 }, (_, i) => start + i);
}

export function Pagination({
  currentPage,
  totalItems,
  pageSize,
  onPageChange,
  maxButtons = 7,
}: PaginationProps) {
  const pageCount = getPageCount(totalItems, pageSize);
  const current = Math.min(Math.max(1, currentPage), pageCount);
  const pages = getPageRange(current, pageCount, maxButtons);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(current - 1)}
            disabled={current <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {pages.map((p) => (
          <li key={p}>
            <button
              onClick={() => onPageChange(p)}
              aria-current={p === current ? "page" : undefined}
              disabled={p === current}
            >
              {p}
            </button>
          </li>
        ))}

        <li>
          <button
            onClick={() => onPageChange(current + 1)}
            disabled={current >= pageCount}
            aria-label="Next page"
          >
            ›
          </button>
        </li>
      </ul>
    </nav>
  );
}
