// Pagination.tsx
import React from "react";

export type PageItem = number | "ellipsis-left" | "ellipsis-right";

/** Builds the list of items to render. With totalPages === 1 this returns [1]. */
export function getPageItems(
  currentPage: number,
  totalPages: number,
  siblings = 1
): PageItem[] {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);

  // Slots: first + last + current + 2*siblings + 2 ellipses
  const maxWithoutEllipsis = 2 * siblings + 5;
  if (total <= maxWithoutEllipsis) {
    return Array.from({ length: total }, (_, i) => i + 1); // total=1 -> [1]
  }

  const left = Math.max(current - siblings, 2);
  const right = Math.min(current + siblings, total - 1);
  const showLeftEllipsis = left > 2;
  const showRightEllipsis = right < total - 1;

  const items: PageItem[] = [1];
  if (showLeftEllipsis) items.push("ellipsis-left");
  for (let p = left; p <= right; p++) items.push(p);
  if (showRightEllipsis) items.push("ellipsis-right");
  items.push(total);
  return items;
}

interface PaginationProps {
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  siblings?: number;
}

export function Pagination({
  currentPage,
  totalPages,
  onPageChange,
  siblings = 1,
}: PaginationProps) {
  const total = Math.max(1, Math.floor(totalPages));
  const current = Math.min(Math.max(1, currentPage), total);
  const items = getPageItems(current, total, siblings);

  return (
    <nav aria-label="Pagination">
