import React from "react";

export interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number;               // 1-based
  onPageChange: (page: number) => void;
  siblingCount?: number;             // pages shown on each side of current
}

type PageItem = number | "ellipsis-left" | "ellipsis-right";

export function getPageItems(
  totalPages: number,
  currentPage: number,
  siblingCount = 1
): PageItem[] {
  // Exactly one page (or zero items): show 1 through 1.
  if (totalPages <= 1) return [1];

  const first = 1;
  const last = totalPages;
  const start = Math.max(currentPage - siblingCount, first + 1);
  const end = Math.min(currentPage + siblingCount, last - 1);

  const items: PageItem[] = [first];
  if (start > first + 1) items.push("ellipsis-left");
  for (let p = start; p <= end; p++) items.push(p);
  if (end < last - 1) items.push("ellipsis-right");
  items.push(last);
  return items;
}

export function Pagination({
  totalItems,
  pageSize,
  currentPage,
  onPageChange,
  siblingCount = 1,
}: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const page = Math.min(Math.max(1, currentPage), totalPages); // clamp
  const items = getPageItems(totalPages, page, siblingCount);

  return (
    <nav aria-label="Pagination">
      <ul style={{ display: "flex", gap: 4, listStyle: "none", padding: 0 }}>
        <li>
          <button
            onClick={() => onPageChange(page - 1)}
            disabled={page <= 1}
            aria-label="Previous page"
          >
            ‹
          </button>
        </li>

        {items.map((item) =>
          typeof item === "number" ? (
            <li key={item}>
              <button
                onClick={() => onPageChange(item)}
                aria-current={item === page ? "page" : undefined}
                disabled={item === page}
              >
                {item}
              </button>
            </li>
          ) : (
            <li key={item} aria-hidden="true">…</li>
          )
        )}

        <li>
          <button
            onClick={() => onPageChange(page + 1)}
            disabled={page >= totalPages}
            aria-label="Next page"
          >
            ›
          </button>
